begin;
set local search_path=public,extensions;
select extensions.no_plan();
insert into public.barbershops(id,name,slug,segment) values('cc100000-0000-4000-8000-000000000001','Artesanato Teste','catalog-evolution-fixture','Artesanato e personalizados');
insert into public.saas_clients(id,name,segment,contact_name,owner_email,origin,plan,monthly_fee,status,barbershop_id)
values('cc200000-0000-4000-8000-000000000001','Artesanato Teste','Artesanato','Fixture','catalog-owner@example.invalid','Teste','Catálogo Essencial',9.90,'Ativo','cc100000-0000-4000-8000-000000000001');
insert into private.billing_signups(id,saas_plan_id,tax_document,business_name,responsible_name,email,phone,cycle,payment_method,base_monthly_cents,cycle_months,discount_bps,total_cents,terms_version,management_token_hash,product_code,barbershop_id,saas_client_id,trial_ends_at)
select 'cc300000-0000-4000-8000-000000000001',id,'00000000001771','Artesanato Teste','Fixture','catalog-owner@example.invalid','11999999999','monthly','pix',990,1,0,990,'fixture','catalog-evolution-fixture','menu','cc100000-0000-4000-8000-000000000001','cc200000-0000-4000-8000-000000000001',now()+interval '14 days'
from public.saas_plans where code='catalogo-essencial';
insert into public.billing_customers(saas_client_id,billing_email) values('cc200000-0000-4000-8000-000000000001','catalog-owner@example.invalid');
insert into public.platform_subscriptions(billing_customer_id,product_id,plan_id,status,billing_cycle,base_amount,current_period_start,current_period_end)
select bc.id,p.product_id,p.id,'trial','monthly',9.90,now(),now()+interval '14 days' from public.billing_customers bc,public.saas_plans p where bc.saas_client_id='cc200000-0000-4000-8000-000000000001' and p.code='catalogo-essencial';
insert into public.business_whatsapp_shares(barbershop_id,phone) values('cc100000-0000-4000-8000-000000000001','5511999999999');
insert into auth.users(id,instance_id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values('cc800000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','catalog-owner@example.invalid','{}','{}',now(),now());
insert into public.profiles(id,barbershop_id,full_name,role,active) values('cc800000-0000-4000-8000-000000000001','cc100000-0000-4000-8000-000000000001','Catalog owner','owner',true);

create temporary table original_contract as select to_jsonb(s) as data from public.platform_subscriptions s join public.billing_customers bc on bc.id=s.billing_customer_id join public.saas_clients client on client.id=bc.saas_client_id where client.barbershop_id='cc100000-0000-4000-8000-000000000001';
create temporary table original_trial as select trial_ends_at from private.billing_signups where barbershop_id='cc100000-0000-4000-8000-000000000001';
select extensions.ok(not has_function_privilege('anon','public.set_catalog_business_segment(uuid,text)','execute'),'anonymous cannot change business activity');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"cc800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.lives_ok($$select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','personalized')$$,'activity can be saved before initial template');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','crafts','saved activity selects the initial presentation');
select public.apply_menu_catalog_template('cc100000-0000-4000-8000-000000000001','crafts','catalog-evolution-fixture');
reset role;
insert into public.menu_items(id,barbershop_id,category_id,name,item_type)
select 'cc600000-0000-4000-8000-000000000001',barbershop_id,id,'Livro Cardápio de Memórias','simple' from public.menu_categories where barbershop_id='cc100000-0000-4000-8000-000000000001' order by sort_order limit 1;
insert into public.menu_item_prices(barbershop_id,menu_item_id,label,price) values('cc100000-0000-4000-8000-000000000001','cc600000-0000-4000-8000-000000000001','Unidade',25);
create temporary table original_catalog as select to_jsonb(m)-'template_code'-'updated_at' as data from public.online_menus m where barbershop_id='cc100000-0000-4000-8000-000000000001';
create temporary table original_items as select jsonb_agg(to_jsonb(i) order by i.id) as data from public.menu_items i where barbershop_id='cc100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"cc800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','made-up')$$,'22023',null,'unknown ids cannot overwrite the stored activity');
select extensions.throws_ok($$select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','Colecionáveis e hobbies')$$,'22023',null,'mutation requires stable ids');
select extensions.throws_ok($$select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000002','food')$$,'42501',null,'activity mutation cannot cross tenant boundaries');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','food');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','food','food: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','food','food: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','pizzeria');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','food','pizzeria: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','pizzeria','pizzeria: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','snack-bar');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','food','snack-bar: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','snack-bar','snack-bar: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','restaurant');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','food','restaurant: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','restaurant','restaurant: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','confectionery');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','food','confectionery: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','confectionery','confectionery: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','crafts');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','crafts','crafts: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','crafts','crafts: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','personalized');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','crafts','personalized: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','personalized','personalized: saved classification is returned after authorization');
