select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','collectibles','collectibles: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','fashion');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','fashion: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','fashion','fashion: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','jewelry');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','jewelry: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','jewelry','jewelry: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','beauty');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','beauty: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','beauty','beauty: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','home-gifts');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','home-gifts: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','home-gifts','home-gifts: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','stationery');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','stationery: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','stationery','stationery: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','books-records');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','books-records: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','books-records','books-records: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','secondhand');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','secondhand: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','secondhand','secondhand: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','pet-accessories');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','pet-accessories: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','pet-accessories','pet-accessories: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','plants');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','plants: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','plants','plants: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','utilities-tech');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','utilities-tech: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','utilities-tech','utilities-tech: saved classification is returned after authorization');
select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','products');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'profile_code','products','products: explicit presentation');
select extensions.is(public.menu_onboarding_status('cc100000-0000-4000-8000-000000000001')->>'segment','products','products: saved classification is returned after authorization');
reset role;
select extensions.is((select to_jsonb(m)-'template_code'-'updated_at' from public.online_menus m where barbershop_id='cc100000-0000-4000-8000-000000000001'),(select data from original_catalog),'switching activities preserves slug, branding, publication and settings');
select extensions.is((select jsonb_agg(to_jsonb(i) order by i.id) from public.menu_items i where barbershop_id='cc100000-0000-4000-8000-000000000001'),(select data from original_items),'switching activities preserves merchant products and descriptions');
select extensions.is((select to_jsonb(s) from public.platform_subscriptions s join public.billing_customers bc on bc.id=s.billing_customer_id join public.saas_clients client on client.id=bc.saas_client_id where client.barbershop_id='cc100000-0000-4000-8000-000000000001'),(select data from original_contract),'switching activities preserves the entire subscription');
select extensions.is((select trial_ends_at from private.billing_signups where barbershop_id='cc100000-0000-4000-8000-000000000001'),(select trial_ends_at from original_trial),'switching activities never restarts trial');
select extensions.is((select segment from public.saas_clients where barbershop_id='cc100000-0000-4000-8000-000000000001'),(select segment from public.barbershops where id='cc100000-0000-4000-8000-000000000001'),'client and shop classification stay synchronized');
select extensions.ok(exists(select 1 from public.platform_billing_audit_log where entity_id='cc100000-0000-4000-8000-000000000001' and action='catalog_segment_changed'),'activity changes have an audit record');
-- Platform administration already writes saas_clients through RLS; the same trigger handles it.
update public.saas_clients set segment='collectibles' where barbershop_id='cc100000-0000-4000-8000-000000000001';
select extensions.is((select template_code from public.online_menus where barbershop_id='cc100000-0000-4000-8000-000000000001'),'products','administrative activity edits synchronize public presentation');
update public.profiles set role='employee' where id='cc800000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"cc800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.throws_ok($$select public.set_catalog_business_segment('cc100000-0000-4000-8000-000000000001','food')$$,'42501',null,'team member without management permission cannot change activity');
reset role;
select extensions.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='set_catalog_business_segment' and p.prosecdef),'public RPC remains an invoker wrapper');
select * from extensions.finish();
rollback;
